def solve(params):
    values = params["values"]
    n = len(values)
    if n == 0:
        return 0
    best = 0
    # enumerate all circular intervals by start and length
    for start in range(n):
        for length in range(1, n+1):
            h = None
            for k in range(length):
                idx = (start + k) % n
                v = values[idx]
                if h is None or v < h:
                    h = v
                    if h == 0:
                        break
            area = h * length if h is not None else 0
            if area > best:
                best = area
    return int(best)
